const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const headers = $input.first().json.headers || {};
const bodyObj = $input.first().json.body || {};
const rawBody = JSON.stringify(bodyObj);
const ts = headers['x-lendloop-timestamp'];
const sig = headers['x-lendloop-signature'];

if (!secret || !ts || !sig) {
  throw new Error('Missing HMAC secret, timestamp, or signature');
}

const expected = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(`${ts}.${rawBody}`)
  .digest('hex');

if (sig !== expected) {
  throw new Error('Invalid incoming HMAC signature from Convex');
}

return [{ json: { ...bodyObj, verified: true } }];

const crypto = require('crypto');
const item = $input.first().json;
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const writebackPayload = JSON.stringify({
  idempotencyKey: `notif:${item.idempotencyKey}`,
  loanId: item.loanId,
  workflowType: 'request_notification',
  eventType: item.eventType,
  summary: `Notified users for ${item.toolName} (${item.eventType})`
});
const ts = String(Date.now());
const sig = 'sha256=' + crypto
  .createHmac('sha256', secret)
  .update(`${ts}.${writebackPayload}`)
  .digest('hex');

return [{
  json: {
    writebackPayload,
    ts,
    sig
  }
}];
